def _fn_matches(fn, glob):
    """Return whether the supplied file name fn matches pattern filename."""
    # Make case-insensitive for better user experience
    fn_lower = fn.lower()
    glob_lower = glob.lower()

    if glob_lower not in _pattern_cache:
        pattern = _pattern_cache[glob_lower] = re.compile(fnmatch.translate(glob_lower), re.IGNORECASE)
        return pattern.match(fn_lower)
    return _pattern_cache[glob_lower].match(fn_lower)
